function design(site, analyse) {
  const xs = [0, 3.963, 7.925, 11.888, 15.85, 19.813, 23.775, 27.738, 31.7];
  const yT = 8.0, yB = -5.5, zL = -4.05, zR = 4.05;
  const nodes = [];
  for (let i = 0; i <= 8; i++) {
    nodes.push({id: "TL" + i, x: xs[i], y: yT, z: zL, joint: "pin"});
    nodes.push({id: "TR" + i, x: xs[i], y: yT, z: zR, joint: "pin"});
    nodes.push({id: "BL" + i, x: xs[i], y: yB, z: zL, joint: "pin"});
    nodes.push({id: "BR" + i, x: xs[i], y: yB, z: zR, joint: "pin"});
  }
  const members = [];
  const add = (a, b, spec) => members.push([a, b, spec]);
  const topChord = "S690 CHS168.3x5 PAINT";
  const botChord = "S690 CHS168.3x5 PAINT";
  const deckChord = "S690 CHS88.9x4 PAINT";
  const vertTop = "S690 CHS88.9x4 PAINT";
  const vertBot = "S690 CHS139.7x5 PAINT";
  const cross = "S690 CHS88.9x4 PAINT";
  const planDiag = "S690 CHS60.3x4 PAINT";
  const topDiagSpecs = [
    "S690 CHS244.5x8 PAINT",
    "S690 CHS219.1x8 PAINT",
    "S690 CHS219.1x8 PAINT",
    "S690 CHS193.7x8 PAINT",
    "S690 CHS193.7x8 PAINT",
    "S690 CHS219.1x8 PAINT",
    "S690 CHS219.1x8 PAINT",
    "S690 CHS244.5x8 PAINT"
  ];
  const botDiagSpecs = [
    "S690 CHS193.7x6.3 PAINT",
    "S690 CHS193.7x6.3 PAINT",
    "S690 CHS168.3x6.3 PAINT",
    "S690 CHS168.3x5 PAINT",
    "S690 CHS168.3x5 PAINT",
    "S690 CHS168.3x6.3 PAINT",
    "S690 CHS193.7x6.3 PAINT",
    "S690 CHS193.7x6.3 PAINT"
  ];
  for (const side of [{d:"L", t:"TL", b:"BL"}, {d:"R", t:"TR", b:"BR"}]) {
    for (let i = 0; i < 8; i++) {
      add(side.t + i, side.t + (i + 1), topChord);
      add(side.b + i, side.b + (i + 1), botChord);
      add(side.d + i, side.d + (i + 1), deckChord);
    }
    for (let i = 0; i <= 8; i++) {
      add(side.d + i, side.t + i, vertTop);
      add(side.d + i, side.b + i, vertBot);
    }
    for (let i = 0; i < 8; i++) {
      add(side.d + i, side.t + (i + 1), topDiagSpecs[i]);
      add(side.d + i, side.b + (i + 1), botDiagSpecs[i]);
    }
  }
  for (let i = 0; i <= 8; i++) {
    add("L" + i, "R" + i, cross);
    add("TL" + i, "TR" + i, cross);
    add("BL" + i, "BR" + i, cross);
  }
  for (let i = 0; i < 8; i++) {
    add("L" + i, "R" + (i + 1), planDiag);
    add("TL" + i, "TR" + (i + 1), planDiag);
    add("BL" + i, "BR" + (i + 1), planDiag);
  }
  const design = {note: "deep space truss baseline", nodes, members};
  let res = analyse(design);
  if (res && res.ok) return design;
  const heavy = {note: "heavy fallback for baseline", nodes, members: members.map(([a, b, s]) => [a, b, "S690 CHS244.5x8 PAINT"])};
  let res2 = analyse(heavy);
  if (res2 && res2.ok) return heavy;
  return heavy;
}

function design(site, analyse) {
  const xs = [0, 3.963, 7.925, 11.888, 15.85, 19.813, 23.775, 27.738, 31.7];

  function build(opt) {
    const nodes = [];
    for (let i = 0; i <= 8; i++) {
      nodes.push({ id: "BL" + i, x: xs[i], y: -5.5, z: -4.05, joint: "pin" });
      nodes.push({ id: "BR" + i, x: xs[i], y: -5.5, z: 4.05, joint: "pin" });
    }

    const members = [];
    const add = (a, b, s) => members.push([a, b, s]);
    const L = i => "L" + i;
    const R = i => "R" + i;
    const BL = i => "BL" + i;
    const BR = i => "BR" + i;

    for (let i = 0; i < 8; i++) {
      // top (deck) chords
      add(L(i), L(i + 1), opt.chord);
      add(R(i), R(i + 1), opt.chord);

      // bottom chords
      add(BL(i), BL(i + 1), opt.chordB || opt.chord);
      add(BR(i), BR(i + 1), opt.chordB || opt.chord);

      // side X diagonals
      add(L(i), BL(i + 1), opt.side);
      add(BL(i), L(i + 1), opt.side);
      add(R(i), BR(i + 1), opt.side);
      add(BR(i), R(i + 1), opt.side);

      // top lateral X
      add(L(i), R(i + 1), opt.lat);
      add(R(i), L(i + 1), opt.lat);

      // bottom lateral X
      add(BL(i), BR(i + 1), opt.latB || opt.lat);
      add(BR(i), BL(i + 1), opt.latB || opt.lat);
    }

    for (let i = 0; i <= 8; i++) {
      // verticals
      add(L(i), BL(i), opt.vert);
      add(R(i), BR(i), opt.vert);

      // transverse cross beams
      add(L(i), R(i), opt.cross);
      add(BL(i), BR(i), opt.crossB || opt.cross);

      // transverse vertical X bracing
      add(L(i), BR(i), opt.trans);
      add(R(i), BL(i), opt.trans);
    }

    return {
      note: "underslung pin-jointed box truss with full X bracing",
      nodes,
      members
    };
  }

  const W = "WIRE WIRE32 GALV";

  const candidates = [
    {
      chord: "S690 CHS193.7x8 PAINT",
      side: "S690 CHS193.7x8 PAINT",
      vert: "S690 CHS168.3x6.3 PAINT",
      cross: "S690 CHS139.7x6.3 PAINT",
      lat: W,
      trans: W
    },
    {
      chord: "S690 CHS193.7x8 PAINT",
      side: "S690 CHS219.1x8 PAINT",
      vert: "S690 CHS168.3x6.3 PAINT",
      cross: "S690 CHS139.7x6.3 PAINT",
      lat: W,
      trans: W
    },
    {
      chord: "S690 CHS193.7x8 PAINT",
      side: "S690 CHS219.1x8 PAINT",
      vert: "S690 CHS139.7x6.3 PAINT",
      cross: "S690 CHS139.7x6.3 PAINT",
      lat: W,
      trans: W
    },
    {
      chord: "S690 CHS193.7x8 PAINT",
      side: "S690 CHS219.1x8 PAINT",
      vert: "S690 CHS168.3x6.3 PAINT",
      cross: "S690 CHS114.3x5 PAINT",
      lat: W,
      trans: W
    },
    {
      chord: "S690 CHS219.1x8 PAINT",
      side: "S690 CHS244.5x8 PAINT",
      vert: "S690 CHS193.7x8 PAINT",
      cross: "S690 CHS168.3x6.3 PAINT",
      lat: "S690 CHS168.3x6.3 PAINT",
      trans: "S690 CHS168.3x6.3 PAINT"
    },
    {
      chord: "S690 CHS244.5x8 PAINT",
      side: "S690 CHS244.5x8 PAINT",
      vert: "S690 CHS193.7x8 PAINT",
      cross: "S690 CHS168.3x6.3 PAINT",
      lat: "S690 CHS168.3x6.3 PAINT",
      trans: "S690 CHS168.3x6.3 PAINT"
    }
  ];

  let best = null;
  let bestMass = Infinity;
  let bestUtil = Infinity;

  for (const c of candidates) {
    const d = build(c);
    let r;
    try {
      r = analyse(d);
    } catch (e) {
      continue;
    }
    if (!r || r.error) continue;
    if (!r.ok || r.mechanism) continue;

    const util = r.maxUtil || 0;
    const sag = r.sag || 0;
    const sagLimit = r.sagLimit || 105.7;
    const sway = r.sway || 0;
    const swayLimit = r.swayLimit || 63.4;

    if (util <= 0.60 && sag <= 0.60 * sagLimit && sway <= 0.60 * swayLimit) {
      if (r.mass < bestMass) {
        bestMass = r.mass;
        best = d;
        bestUtil = util;
      }
    }
  }

  if (best) {
    best.note += " selected by static search; util=" + bestUtil.toFixed(2);
    return best;
  }

  const fallback = build(candidates[5]);
  fallback.note = "conservative fully-braced fallback";
  return fallback;
}

function design(site, analyse) {
  const xs = [0, 3.963, 7.925, 11.888, 15.85, 19.813, 23.775, 27.738, 31.7];
  const yB = -5.6;

  const S = {
    c1145: "S690 CHS114.3x5 PAINT",
    c1395: "S690 CHS139.7x5 PAINT",
    c13963: "S690 CHS139.7x6.3 PAINT",
    c1685: "S690 CHS168.3x5 PAINT",
    c16863: "S690 CHS168.3x6.3 PAINT",
    c19363: "S690 CHS193.7x6.3 PAINT",
    c1938: "S690 CHS193.7x8 PAINT",
    c2198: "S690 CHS219.1x8 PAINT",
    c2448: "S690 CHS244.5x8 PAINT"
  };

  function build(opt) {
    const nodes = [];
    for (let j = 0; j < 8; j++) {
      const x = (xs[j] + xs[j + 1]) / 2;
      nodes.push({ id: "B" + j, x: x, y: yB, z: 0, joint: "pin-bolted" });
    }

    const members = [];
    const add = (a, b, s) => members.push([a, b, s]);

    // top chords (deck edges)
    for (let i = 0; i < 8; i++) {
      add("L" + i, "L" + (i + 1), opt.top[i]);
      add("R" + i, "R" + (i + 1), opt.top[i]);
    }

    // single central bottom chord
    for (let j = 0; j < 7; j++) {
      add("B" + j, "B" + (j + 1), opt.bot[j]);
    }

    // four diagonals from each central bottom node to adjacent top corners
    for (let i = 0; i < 8; i++) {
      const s = opt.diag[i];
      add("L" + i, "B" + i, s);
      add("L" + (i + 1), "B" + i, s);
      add("R" + i, "B" + i, s);
      add("R" + (i + 1), "B" + i, s);
    }

    // top transverse cross members at every deck station
    for (let i = 0; i <= 8; i++) {
      add("L" + i, "R" + i, opt.cross);
    }

    // one zig-zag top lateral diagonal per panel for in-plane rigidity
    if (opt.topLat) {
      for (let i = 0; i < 8; i++) {
        if (i % 2 === 0) add("L" + i, "R" + (i + 1), opt.topLat);
        else add("R" + i, "L" + (i + 1), opt.topLat);
      }
    }

    const joints = {};
    for (let i = 0; i <= 8; i++) {
      joints["L" + i] = "pin-bolted";
      joints["R" + i] = "pin-bolted";
    }

    return { note: opt.note, nodes: nodes, joints: joints, members: members };
  }

  const candidates = [
    {
      note: "light triangular-spine truss, variable chords and diagonals",
      top: [S.c1145, S.c1685, S.c19363, S.c1938, S.c1938, S.c19363, S.c1685, S.c1145],
      bot: [S.c1145, S.c16863, S.c19363, S.c1938, S.c19363, S.c16863, S.c1145],
      diag: [S.c2448, S.c2198, S.c1938, S.c1685, S.c1685, S.c1938, S.c2198, S.c2448],
      cross: S.c1685,
      topLat: S.c1685
    },
    {
      note: "triangular-spine, heavier central chords and middle diagonals",
      top: [S.c1395, S.c1685, S.c19363, S.c2198, S.c2198, S.c19363, S.c1685, S.c1395],
      bot: [S.c1395, S.c16863, S.c1938, S.c2198, S.c1938, S.c16863, S.c1395],
      diag: [S.c2448, S.c2198, S.c1938, S.c1938, S.c1938, S.c1938, S.c2198, S.c2448],
      cross: S.c16863,
      topLat: S.c1685
    },
    {
      note: "triangular-spine medium-heavy",
      top: [S.c1685, S.c19363, S.c2198, S.c2198, S.c2198, S.c2198, S.c19363, S.c1685],
      bot: [S.c16863, S.c1938, S.c2198, S.c2198, S.c2198, S.c1938, S.c16863],
      diag: [S.c2448, S.c2198, S.c2198, S.c1938, S.c1938, S.c2198, S.c2198, S.c2448],
      cross: S.c19363,
      topLat: S.c16863
    },
    {
      note: "triangular-spine heavy central chords, strong bracing",
      top: [S.c1938, S.c2198, S.c2448, S.c2448, S.c2448, S.c2448, S.c2198, S.c1938],
      bot: [S.c19363, S.c2198, S.c2448, S.c2448, S.c2448, S.c2198, S.c19363],
      diag: [S.c2448, S.c2448, S.c2198, S.c2198, S.c2198, S.c2198, S.c2448, S.c2448],
      cross: S.c1938,
      topLat: S.c19363
    },
    {
      note: "triangular-spine conservative",
      top: [S.c16863, S.c1938, S.c2448, S.c2448, S.c2448, S.c2448, S.c1938, S.c16863],
      bot: [S.c16863, S.c1938, S.c2198, S.c2448, S.c2198, S.c1938, S.c16863],
      diag: Array(8).fill(S.c2448),
      cross: S.c1938,
      topLat: S.c19363
    },
    {
      note: "triangular-spine very heavy",
      top: Array(8).fill(S.c2448),
      bot: Array(7).fill(S.c2448),
      diag: Array(8).fill(S.c2448),
      cross: S.c2198,
      topLat: S.c1938
    },
    {
      note: "triangular-spine fallback all 244.5x8",
      top: Array(8).fill(S.c2448),
      bot: Array(7).fill(S.c2448),
      diag: Array(8).fill(S.c2448),
      cross: S.c2448,
      topLat: S.c2448
    }
  ];

  let bestStrict = null;
  let bestRelax = null;
  let bestAny = null;

  for (const opt of candidates) {
    const d = build(opt);
    let r;
    try {
      r = analyse(d);
    } catch (e) {
      continue;
    }
    if (!r || r.error || !r.ok || r.mechanism) continue;

    let compMax = 0;
    let otherMax = 0;
    if (r.members) {
      for (const m of r.members) {
        const u = Number(m.util) || 0;
        const mode = String(m.mode || "").toLowerCase();
        if (mode.indexOf("buckl") >= 0 || mode.indexOf("compress") >= 0) {
          if (u > compMax) compMax = u;
        } else {
          if (u > otherMax) otherMax = u;
        }
      }
    } else {
      compMax = Number(r.maxUtil) || 0;
    }

    const sag = Number(r.sag) || 999;
    const sway = Number(r.sway) || 999;
    const mass = Number(r.mass) || 1e9;

    // rough first vertical-frequency estimate from the crowd-case sag
    const deckMass = 117790; // kg (4.5 kN/m2 over full deck)
    const M = mass + deckMass;
    const P = 2 * 8.1 * 31.7 * 1000; // N, full-width crowd
    let f_est = null;
    if (sag > 0 && sag < 999) {
      const sag_m = sag / 1000;
      const delta_sw = sag_m * (M * 9.81 / P);
      f_est = 0.561 / Math.sqrt(delta_sw);
    }

    const info = { d: d, compMax: compMax, otherMax: otherMax, sag: sag, sway: sway, mass: mass, f_est: f_est };
    if (!bestAny || mass < bestAny.mass) bestAny = info;

    const freqOK = f_est === null || f_est > 2.4 || (f_est < 1.55 && sag > 45);

    if (compMax <= 0.60 && otherMax <= 0.85 && sag <= 18 && sway <= 14 &&
        f_est !== null && (f_est > 2.65 || (f_est < 1.50 && sag > 50))) {
      if (!bestStrict || mass < bestStrict.mass) bestStrict = info;
    }

    if (compMax <= 0.72 && otherMax <= 0.90 && sag <= 24 && sway <= 20 && freqOK) {
      if (!bestRelax || mass < bestRelax.mass) bestRelax = info;
    }
  }

  let chosen;
  if (bestStrict) chosen = bestStrict;
  else if (bestRelax) chosen = bestRelax;
  else if (bestAny) chosen = bestAny;
  else {
    const fb = build(candidates[candidates.length - 1]);
    fb.note += " [fallback]";
    fb.final = true;
    return fb;
  }

  const ret = chosen.d;
  ret.note += " selected; mass~" + Math.round(chosen.mass) +
              " kg; compMax=" + chosen.compMax.toFixed(2) +
              "; sag=" + chosen.sag.toFixed(1) +
              " mm; sway=" + chosen.sway.toFixed(1) + " mm";
  ret.final = true;
  return ret;
}

function design(site, analyse) {
  const xs = [0, 3.963, 7.925, 11.888, 15.85, 19.813, 23.775, 27.738, 31.7];

  const T = {
    s114: "S690 CHS114.3x5 PAINT",
    s139: "S690 CHS139.7x5 PAINT",
    s168_5: "S690 CHS168.3x5 PAINT",
    s168_63: "S690 CHS168.3x6.3 PAINT",
    s193_63: "S690 CHS193.7x6.3 PAINT",
    s193_8: "S690 CHS193.7x8 PAINT",
    s219: "S690 CHS219.1x8 PAINT",
    s244: "S690 CHS244.5x8 PAINT",
    s273: "S690 CHS273x10 PAINT"
  };

  function build(v) {
    const nodes = [];
    for (let j = 0; j < 8; j++) {
      const x = (xs[j] + xs[j + 1]) / 2;
      nodes.push({ id: "B" + j, x: x, y: v.yB, z: 0, joint: v.jointType });
    }

    const joints = {};
    for (let i = 0; i <= 8; i++) {
      joints["L" + i] = v.jointType;
      joints["R" + i] = v.jointType;
    }

    const members = [];
    const add = (a, b, s) => members.push([a, b, s]);

    // top deck-edge chords
    for (let i = 0; i < 8; i++) {
      add("L" + i, "L" + (i + 1), v.top[i]);
      add("R" + i, "R" + (i + 1), v.top[i]);
    }

    // central bottom spine
    for (let j = 0; j < 7; j++) {
      add("B" + j, "B" + (j + 1), v.bot[j]);
    }

    // four diagonals per bottom node to the adjacent deck panel corners
    for (let j = 0; j < 8; j++) {
      const s = v.diag[j];
      add("L" + j, "B" + j, s);
      add("L" + (j + 1), "B" + j, s);
      add("R" + j, "B" + j, s);
      add("R" + (j + 1), "B" + j, s);
    }

    // transverse deck cross members
    for (let i = 0; i <= 8; i++) {
      add("L" + i, "R" + i, v.cross[i]);
    }

    // top lateral zig-zag bracing
    for (let i = 0; i < 8; i++) {
      if (i % 2 === 0) add("L" + i, "R" + (i + 1), v.lat[i]);
      else add("R" + i, "L" + (i + 1), v.lat[i]);
    }

    return {
      note: v.note,
      final: true,
      nodes: nodes,
      joints: joints,
      members: members
    };
  }

  // Safe tailored design:
  // - Strong T8 end diagonals, T7 next panels, T5 quarter panels, T4 centre.
  // - Heavy central bottom spine; lighter ends.
  // - Welded joints to improve fatigue.
  const finalSafe = {
    note: "Tailored triangular-spine truss: strong end diagonals, heavy central spine, welded joints; balanced for stiffness, buckling and fatigue.",
    yB: -5.6,
    jointType: "pin", // pin-welded
    top:   [T.s168_63, T.s193_63, T.s193_8, T.s219, T.s219, T.s193_8, T.s193_63, T.s168_63],
    bot:   [T.s168_63, T.s193_8, T.s244, T.s244, T.s244, T.s193_8, T.s168_63],
    diag:  [T.s273, T.s244, T.s193_8, T.s193_63, T.s193_63, T.s193_8, T.s244, T.s273],
    cross: [T.s244, T.s193_8, T.s193_63, T.s168_63, T.s168_5, T.s168_63, T.s193_63, T.s193_8, T.s244],
    lat:   [T.s193_8, T.s193_63, T.s193_63, T.s193_63, T.s193_63, T.s193_63, T.s193_63, T.s193_8]
  };

  // Known-good fallback: attempt 3 heavy triangular spine.
  const current3 = {
    note: "Fallback to known heavy attempt-3 triangular-spine truss.",
    yB: -5.6,
    jointType: "pin-bolted",
    top:   Array(8).fill(T.s244),
    bot:   Array(7).fill(T.s244),
    diag:  Array(8).fill(T.s244),
    cross: Array(9).fill(T.s219),
    lat:   Array(8).fill(T.s193_8)
  };

  let chosen = build(finalSafe);

  let r = null;
  try {
    r = analyse(chosen);
  } catch (e) {
    r = null;
  }

  if (!r || r.error || !r.ok || r.mechanism) {
    chosen = build(current3);
    chosen.note = "Fallback to known attempt-3 heavy triangular-spine truss.";
  }

  chosen.final = true;
  return chosen;
}

