      const kk = [
        [k * ex * ex, k * ex * ey, k * ex * ez],
        [k * ey * ex, k * ey * ey, k * ey * ez],
        [k * ez * ex, k * ez * ey, k * ez * ez]
      ];
      const dofsA = [3 * a, 3 * a + 1, 3 * a + 2];
      const dofsB = [3 * b, 3 * b + 1, 3 * b + 2];
      for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) {
        K[dofsA[i]][dofsA[j]] += kk[i][j];
        K[dofsB[i]][dofsB[j]] += kk[i][j];
        K[dofsA[i]][dofsB[j]] -= kk[i][j];
        K[dofsB[i]][dofsA[j]] -= kk[i][j];
      }
      const mt = pr.A * L * 7.85;
      massNode[a] += mt / 2; massNode[b] += mt / 2;
      conns[a].push(pr.mpm); conns[b].push(pr.mpm);
    }
    for (let i = 0; i < Nn; i++) {
      let sum = 0;
      for (const v of conns[i]) sum += v;
      massNode[i] += (12 + 0.35 * sum) / 1000;
    }
    for (let i = 0; i <= 8; i++) {
      const len = (i === 0 || i === 8) ? (xs[1] - xs[0]) / 2 : (xs[1] - xs[0]);
      const area = len * 4.05;
      const dm = 4.5 * area / 9.81;
      massNode[map["L" + i]] += dm;
      massNode[map["R" + i]] += dm;
    }
    const fixed = Array(NDOF).fill(false);
    function fix(id, dirs) {
      const idx = map[id];
      for (const d of dirs) fixed[3 * idx + d] = true;
    }
    fix("L0", [0, 1, 2]);
    fix("R0", [0, 1]);
    fix("L8", [1, 2]);
    fix("R8", [1]);
    const freeDofs = [], freeIndex = Array(NDOF).fill(-1);
    for (let g = 0; g < NDOF; g++) if (!fixed[g]) {
      freeIndex[g] = freeDofs.length;
      freeDofs.push(g);
    }
    const nf = freeDofs.length;
    const Kr = Array.from({ length: nf }, () => Array(nf).fill(0));
    for (let i = 0; i < nf; i++) for (let j = 0; j < nf; j++) Kr[i][j] = K[freeDofs[i]][freeDofs[j]];
    const Md = Array(nf);
    for (let i = 0; i < nf; i++) {
      const g = freeDofs[i];
      Md[i] = massNode[Math.floor(g / 3)];
    }
    const A = Array.from({ length: nf }, () => Array(nf).fill(0));
    for (let i = 0; i < nf; i++) for (let j = 0; j < nf; j++) {
      A[i][j] = Kr[i][j] / Math.sqrt(Md[i] * Md[j]);
    }
    const { values, vectors } = eigenSym(A, nf);
    let bad = false, minF = Infinity;
    const modes = [];
    for (let m = 0; m < nf; m++) {
      const f = Math.sqrt(Math.max(0, values[m])) / (2 * Math.PI);
      if (f < minF) minF = f;
      if (f < 1.0) bad = true;
      let vert = 0, horiz = 0, tot = 0;
      for (let i = 0; i < nf; i++) {
        const v2 = vectors[i][m] * vectors[i][m];
        tot += v2;
        const g = freeDofs[i];
        if (g % 3 === 1) vert += v2;
        else horiz += v2;
      }
      const vs = tot > 0 ? vert / tot : 0;
      const hs = tot > 0 ? horiz / tot : 0;
      if (f >= 1.6 && f <= 2.42 && vs >= 0.20) bad = true;
      if (f >= 0.56 && f <= 1.2 && hs >= 0.20) bad = true;
      modes.push({ f: f, vs: vs, hs: hs });
    }
    return { bad: bad, minF: minF, modes: modes, Kr: Kr, freeDofs: freeDofs, freeIndex: freeIndex, map: map, nodes: nodes };
  }

  function estimateAlpha(design, r, freqRes) {
    if (!r || !r.members || r.members.length !== design.members.length) return { alpha: Infinity, minRatio: Infinity };
    const { Kr, freeIndex, map, nodes } = freqRes;
    const nf = Kr.length;
    const invK = inv(Kr);
    if (!invK) return { alpha: 0, minRatio: 0 };
    const B = Array.from({ length: nf }, () => Array(nf).fill(0));
    let minRatio = Infinity;
    for (let mi = 0; mi < design.members.length; mi++) {
      const mem = design.members[mi];
      const comp = Math.abs(Number(r.members[mi].compression) || 0);
      if (comp <= 1e-9) continue;
      const a = map[mem[0]], b = map[mem[1]];
      const na = nodes[a], nb = nodes[b];
      const dx = nb.x - na.x, dy = nb.y - na.y, dz = nb.z - na.z;
      const L = Math.sqrt(dx * dx + dy * dy + dz * dz);
      if (L < 1e-6) continue;
      const ex = dx / L, ey = dy / L, ez = dz / L;
      const pr = getProp(mem[2]);
      const Ncr = Math.PI * Math.PI * pr.E * pr.I / (L * L);
      const ratio = Ncr / comp;
      if (ratio < minRatio) minRatio = ratio;
      const mat = [
        [1 - ex * ex, -ex * ey, -ex * ez],
        [-ey * ex, 1 - ey * ey, -ey * ez],
        [-ez * ex, -ez * ey, 1 - ez * ez]
      ];
      const fac = comp / L;
      const dofsA = [3 * a, 3 * a + 1, 3 * a + 2];
      const dofsB = [3 * b, 3 * b + 1, 3 * b + 2];
      const idxA = dofsA.map(g => freeIndex[g]);
      const idxB = dofsB.map(g => freeIndex[g]);
      for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) {
        const val = fac * mat[i][j];
        if (idxA[i] >= 0 && idxA[j] >= 0) B[idxA[i]][idxA[j]] += val;
        if (idxB[i] >= 0 && idxB[j] >= 0) B[idxB[i]][idxB[j]] += val;
        if (idxA[i] >= 0 && idxB[j] >= 0) B[idxA[i]][idxB[j]] -= val;
        if (idxB[i] >= 0 && idxA[j] >= 0) B[idxB[i]][idxA[j]] -= val;
      }
    }
    if (minRatio === Infinity) minRatio = 1e9;
    const Cmat = Array.from({ length: nf }, () => Array(nf).fill(0));
    for (let i = 0; i < nf; i++) for (let k = 0; k < nf; k++) {
      const aik = invK[i][k];
      if (Math.abs(aik) < 1e-15) continue;
      for (let j = 0; j < nf; j++) Cmat[i][j] += aik * B[k][j];
    }
    let x = Array(nf).fill(1 / Math.sqrt(nf));
    let mu = 0;
    for (let iter = 0; iter < 200; iter++) {
      const y = Array(nf).fill(0);
      for (let i = 0; i < nf; i++) {
        let sum = 0;
        for (let j = 0; j < nf; j++) sum += Cmat[i][j] * x[j];
        y[i] = sum;
      }
      let norm = 0;
      for (let i = 0; i < nf; i++) norm += y[i] * y[i];
      norm = Math.sqrt(norm);
      if (norm < 1e-12) { mu = 0; break; }
      for (let i = 0; i < nf; i++) x[i] = y[i] / norm;
      mu = norm;
    }
    const alpha = mu > 1e-12 ? 1 / mu : Infinity;
    return { alpha: alpha, minRatio: minRatio };
  }

  const results = [];
  for (const cand of candidates) {
    const d = build(cand);
    let r = null;
    try { r = analyse(d); } catch (e) { continue; }
    if (!r || r.error || !r.ok || r.mechanism) continue;
    let freqRes = null, freqPass = false, minF = Infinity;
    try {
      freqRes = checkFrequency(d);
      freqPass = !freqRes.bad;
      minF = freqRes.minF;
    } catch (e) {}
    let alpha = Infinity, minRatio = Infinity;
    if (freqRes) {
      try {
        const ares = estimateAlpha(d, r, freqRes);
        alpha = ares.alpha;
        minRatio = ares.minRatio;
      } catch (e) {}
    }
    const maxUtil = Number(r.maxUtil) || 0;
    const sag = Number(r.sag) || 0;
    const sway = Number(r.sway) || 0;
    const mass = Number(r.mass) || Infinity;
    results.push({ d: d, r: r, mass: mass, maxUtil: maxUtil, sag: sag, sway: sway, freqPass: freqPass, minF: minF, alpha: alpha, minRatio: minRatio });
  }

  const tiers = [
    q => q.maxUtil <= 0.55 && q.sag <= 90 && q.sway <= 50 && q.freqPass && q.alpha >= 3.5 && q.minRatio >= 3.2,
    q => q.maxUtil <= 0.65 && q.sag <= 100 && q.sway <= 58 && q.freqPass && q.alpha >= 3.2 && q.minRatio >= 3.0,
    q => q.maxUtil <= 0.75 && q.sag <= 105 && q.sway <= 63 && q.freqPass && q.alpha >= 3.0 && q.minRatio >= 3.0,
    q => q.maxUtil <= 0.75 && q.sag <= 105 && q.sway <= 63 && (q.freqPass || q.alpha >= 3.0 || q.minRatio >= 3.0),
    q => q.maxUtil <= 0.85 && q.sag <= 105 && q.sway <= 63 && (q.freqPass || q.alpha >= 2.5)
  ];
  let chosen = null;
  for (const cond of tiers) {
    const pool = results.filter(cond);
    if (pool.length) {
      chosen = pool.reduce((a, b) => a.mass < b.mass ? a : b);
      break;
    }
  }
  if (!chosen) {
    const pool = results.filter(q => q.r.ok && !q.r.mechanism);
    if (pool.length) chosen = pool.reduce((a, b) => a.mass < b.mass ? a : b);
  }
  if (!chosen) {
    const d = build(candidates[0]);
    d.final = true;
    return d;
  }
  chosen.d.final = true;
  chosen.d.note = (chosen.d.note || "") + " selected mass " + Math.round(chosen.mass) +
                  " maxUtil " + chosen.maxUtil.toFixed(2) +
                  " sag " + chosen.sag.toFixed(1) +
                  " minF " + chosen.minF.toFixed(2) +
                  " alpha " + chosen.alpha.toFixed(2);
  return chosen.d;
}

function design(site, analyse) {
  const xs = [0, 3.963, 7.925, 11.888, 15.85, 19.813, 23.775, 27.738, 31.7];

