  results.sort((a, b) => a.mass - b.mass);

  function fullNodes(design) {
    const nodes = [];
    const map = {};
    for (let i = 0; i <= 8; i++) {
      map["L" + i] = nodes.length;
      nodes.push({ id: "L" + i, x: xs[i], y: 0, z: -4.05 });
