  function matVec(A, v) {
    const n = A.length;
    const y = Array(n).fill(0);
    for (let i = 0; i < n; i++) {
      let s = 0;
      const row = A[i];
      for (let j = 0; j < n; j++) s += row[j] * v[j];
      y[i] = s;
    }
    return y;
  }

  function invMat(M) {
    const n = M.length;
    const A = M.map((row, i) => {
      const r = row.slice();
      for (let j = 0; j < n; j++) r.push(i === j ? 1 : 0);
      return r;
    });
    for (let i = 0; i < n; i++) {
      let piv = i;
      for (let r = i + 1; r < n; r++) {
        if (Math.abs(A[r][i]) > Math.abs(A[piv][i])) piv = r;
      }
      if (Math.abs(A[piv][i]) < 1e-14) return null;
      if (piv !== i) {
        const tmp = A[i]; A[i] = A[piv]; A[piv] = tmp;
      }
      const div = A[i][i];
      for (let j = i; j < 2 * n; j++) A[i][j] /= div;
      for (let r = 0; r < n; r++) {
        if (r === i) continue;
        const fac = A[r][i];
        if (Math.abs(fac) < 1e-15) continue;
        for (let j = i; j < 2 * n; j++) A[r][j] -= fac * A[i][j];
      }
    }
    return A.map(row => row.slice(n));
  }

  function jacobiEigen(Ain) {
    const n = Ain.length;
    const A = Ain.map(r => r.slice());
    const V = Array.from({ length: n }, (_, i) => {
      const r = Array(n).fill(0);
      r[i] = 1;
      return r;
    });

    for (let sweep = 0; sweep < 100; sweep++) {
      let off = 0;
      for (let p = 0; p < n - 1; p++) {
        for (let q = p + 1; q < n; q++) off += A[p][q] * A[p][q];
      }
      if (off < 1e-24) break;

      for (let p = 0; p < n - 1; p++) {
        for (let q = p + 1; q < n; q++) {
          if (Math.abs(A[p][q]) < 1e-18) continue;
          const app = A[p][p];
          const aqq = A[q][q];
          const apq = A[p][q];
          const theta = 0.5 * Math.atan2(2 * apq, app - aqq);
          const c = Math.cos(theta);
          const s = Math.sin(theta);
          for (let i = 0; i < n; i++) {
            if (i !== p && i !== q) {
              const aip = A[i][p];
              const aiq = A[i][q];
              A[i][p] = c * aip - s * aiq;
              A[p][i] = A[i][p];
              A[i][q] = s * aip + c * aiq;
              A[q][i] = A[i][q];
            }
          }
          A[p][p] = c * c * app - 2 * s * c * apq + s * s * aqq;
          A[q][q] = s * s * app + 2 * s * c * apq + c * c * aqq;
          A[p][q] = A[q][p] = 0;

          for (let i = 0; i < n; i++) {
            const vip = V[i][p];
            const viq = V[i][q];
            V[i][p] = c * vip - s * viq;
            V[i][q] = s * vip + c * viq;
          }
        }
      }
    }

    const cols = [];
    for (let i = 0; i < n; i++) cols.push({ val: A[i][i], col: i });
    cols.sort((a, b) => a.val - b.val);

    return {
      values: cols.map(o => o.val),
      vectors: cols.map(o => V.map(row => row[o.col]))
    };
  }

  function buildFE(design) {
    const { nodes, map } = fullNodes(design);
    const n = nodes.length * 3;
    const K = Array.from({ length: n }, () => Array(n).fill(0));
    const massNode = Array(nodes.length).fill(0);
    const sumMpm = Array(nodes.length).fill(0);
    const memberData = [];

    for (const mem of design.members) {
