      if (L < 1e-9) continue;
      const ex = dx / L, ey = dy / L, ez = dz / L;
      const pr = defs[spec] || defs[T273];

      const k = pr.E * pr.A / L;
      const kk = [
        [k * ex * ex, k * ex * ey, k * ex * ez],
        [k * ey * ex, k * ey * ey, k * ey * ez],
        [k * ez * ex, k * ez * ey, k * ez * ez]
      ];
      const da = [3 * ia, 3 * ia + 1, 3 * ia + 2];
      const db = [3 * ib, 3 * ib + 1, 3 * ib + 2];
      for (let i = 0; i < 3; i++) {
        for (let j = 0; j < 3; j++) {
          K[da[i]][da[j]] += kk[i][j];
          K[db[i]][db[j]] += kk[i][j];
          K[da[i]][db[j]] -= kk[i][j];
          K[db[i]][da[j]] -= kk[i][j];
        }
      }

      const mt = pr.mpm * L / 1000 / 2; // tonnes per half member
      massNode[ia] += mt;
      massNode[ib] += mt;
      sumMpm[ia] += pr.mpm;
      sumMpm[ib] += pr.mpm;

      memberData.push({ ia, ib, L, ex, ey, ez, spec, pr });
    }

    // Joint masses (all pinned).
    for (let i = 0; i < nodes.length; i++) {
      massNode[i] += (12 + 0.35 * sumMpm[i]) / 1000;
    }

    // Deck dead load lumps.
    for (let i = 0; i <= 8; i++) {
      const len = (i === 0 || i === 8) ? (xs[1] - xs[0]) / 2 : (xs[1] - xs[0]);
      const dm = 4.5 * len * 4.05 / 9.81; // tonnes
      if (map["L" + i] !== undefined) massNode[map["L" + i]] += dm;
      if (map["R" + i] !== undefined) massNode[map["R" + i]] += dm;
    }

    // Bearing springs: horizontal restraints effectively rigid, vertical soft.
    const kL0 = (433.3 + 458.8 + 577.8) / 3 * 1000;
    const kR0 = (423.1 + 326.7 + 353.7) / 3 * 1000;
    const kL8 = (162.4 + 185.3 + 176.3) / 3 * 1000;
    const kR8 = (423.4 + 339.1 + 390.1) / 3 * 1000;

    function addSpring(id, dir, k) {
      const idx = map[id];
      if (idx === undefined) return;
      K[3 * idx + dir][3 * idx + dir] += k;
    }
    addSpring("L0", 0, 1e9);
    addSpring("L0", 1, kL0);
    addSpring("L0", 2, 1e9);
    addSpring("R0", 0, 1e9);
    addSpring("R0", 1, kR0);
    addSpring("L8", 1, kL8);
    addSpring("L8", 2, 1e9);
    addSpring("R8", 1, kR8);

    return { K, massNode, memberData, nodes, map };
  }

  function checkModes(design, fe) {
    const K = fe.K;
    const n = K.length;
    const mDof = Array(n).fill(0);
    for (let i = 0; i < fe.nodes.length; i++) {
      for (let d = 0; d < 3; d++) mDof[3 * i + d] = fe.massNode[i];
    }

    const A = Array.from({ length: n }, () => Array(n).fill(0));
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < n; j++) {
        A[i][j] = K[i][j] / Math.sqrt(mDof[i] * mDof[j]);
      }
    }

    const eig = jacobiEigen(A);
    let minF = Infinity;
    let bad = false;
    const modes = [];

    for (let m = 0; m < eig.values.length; m++) {
      const f = Math.sqrt(Math.max(0, eig.values[m])) / (2 * Math.PI);
      if (f < 1.0) bad = true;
      if (f < minF) minF = f;

      const vec = eig.vectors[m];
      let vert = 0, horiz = 0, tot = 0;
      for (let g = 0; g < n; g++) {
        const x = vec[g];
        const ke = x * x;
        tot += ke;
        if (g % 3 === 1) vert += ke;
        else horiz += ke;
      }
      const vs = tot > 0 ? vert / tot : 0;
      const hs = tot > 0 ? horiz / tot : 0;

      if (f >= 1.6 && f <= 2.42 && vs >= 0.25) bad = true;
      if (f >= 0.56 && f <= 1.2 && hs >= 0.25) bad = true;

      if (f < 4.0) modes.push({ f, vs, hs });
    }

    return { bad, minF, modes };
  }

  function computeAlpha(design, fe, r) {
    const n = fe.K.length;
    const B = Array.from({ length: n }, () => Array(n).fill(0));

    for (let mi = 0; mi < design.members.length; mi++) {
      const md = fe.memberData[mi];
      if (!md) continue;
      const mm = r.members && r.members[mi];
      if (!mm) continue;
      const N = Math.abs(Number(mm.compression) || 0);
      if (N <= 0.01) continue;

      const { ia, ib, L, ex, ey, ez } = md;
      const fac = N / L;
      const exx = ex * ex, eyy = ey * ey, ezz = ez * ez;
      const exy = ex * ey, exz = ex * ez, eyz = ey * ez;
      const mat = [
        [1 - exx, -exy, -exz],
        [-exy, 1 - eyy, -eyz],
        [-exz, -eyz, 1 - ezz]
      ];
      const da = [3 * ia, 3 * ia + 1, 3 * ia + 2];
      const db = [3 * ib, 3 * ib + 1, 3 * ib + 2];
      for (let i = 0; i < 3; i++) {
        for (let j = 0; j < 3; j++) {
          const val = fac * mat[i][j];
          B[da[i]][da[j]] += val;
          B[db[i]][db[j]] += val;
          B[da[i]][db[j]] -= val;
          B[db[i]][da[j]] -= val;
        }
      }
    }

    const invK = invMat(fe.K);
    if (!invK) return 0;

    // C = K^{-1} B
    const C = Array.from({ length: n }, () => Array(n).fill(0));
    for (let i = 0; i < n; i++) {
      for (let k = 0; k < n; k++) {
        const aik = invK[i][k];
        if (Math.abs(aik) < 1e-15) continue;
        for (let j = 0; j < n; j++) C[i][j] += aik * B[k][j];
      }
    }

    let x = Array(n).fill(1 / Math.sqrt(n));
    let mu = 0;
    for (let iter = 0; iter < 100; iter++) {
      const y = matVec(C, x);
      let norm = 0;
      for (let i = 0; i < n; i++) norm += y[i] * y[i];
      norm = Math.sqrt(norm);
      if (norm < 1e-13) { mu = 0; break; }
      for (let i = 0; i < n; i++) x[i] = y[i] / norm;
      mu = norm;
    }
    return mu > 1e-12 ? 1 / mu : Infinity;
  }

  function computeCompUtil(design, fe, r) {
    const fy = 690e3; // kN/m2
    const E = 2.1e8;  // kN/m2
    const gammaM = 1.25;
    const alphaImp = 0.21;
    let maxU = 0;

    for (let mi = 0; mi < design.members.length; mi++) {
      const md = fe.memberData[mi];
      if (!md) continue;
      const mm = r.members && r.members[mi];
      if (!mm) continue;
      const N = Math.abs(Number(mm.compression) || 0);
      if (N <= 0) continue;

      const A = md.pr.A;
      const I = md.pr.I;
      const L = md.L;
      const Ncr = Math.PI * Math.PI * E * I / (L * L);
      const lambda = Math.sqrt(A * fy / Math.max(1e-9, Ncr));
      const Phi = 0.5 * (1 + alphaImp * (lambda - 0.2) + lambda * lambda);
      const root = Math.sqrt(Math.max(0, Phi * Phi - lambda * lambda));
      let chi = 1 / (Phi + root);
      if (!isFinite(chi) || chi > 1) chi = 1;
      const cap = chi * A * fy / gammaM;
      const u = N / Math.max(1e-9, cap);
      if (u > maxU) maxU = u;
    }
    return maxU;
  }

  function computeMaxStress(design, fe, r) {
    let maxS = 0;
    for (let mi = 0; mi < design.members.length; mi++) {
      const md = fe.memberData[mi];
      if (!md) continue;
      const mm = r.members && r.members[mi];
      if (!mm) continue;
      const N = Math.max(
        Number(mm.tension) || 0,
        Number(mm.compression) || 0
      );
      const stress = N / Math.max(1e-9, md.pr.A) / 1000; // MPa
      if (stress > maxS) maxS = stress;
    }
    return maxS;
  }

  function hasRiskyClass(design, fe, r) {
    for (let mi = 0; mi < design.members.length; mi++) {
      const md = fe.memberData[mi];
      if (!md) continue;
      if (md.spec.indexOf("244.5x8") >= 0) {
        const mm = r.members && r.members[mi];
        const comp = Number(mm && mm.compression) || 0;
        if (comp > 100) return true;
      }
    }
    return false;
  }

  let bestAny = null;

  for (const res of results) {
    const r = res.r;
    if (!r.ok || r.mechanism) continue;
    if (Number(r.maxUtil) > 0.85) continue;
    if (Number(r.sag) > 90) continue;
    if (Number(r.sway) > 45) continue;

    let fe;
    let mres, alpha, compMax, stressMax, risky;
    try {
      fe = buildFE(res.d);
      mres = checkModes(res.d, fe);
      alpha = computeAlpha(res.d, fe, r);
      compMax = computeCompUtil(res.d, fe, r);
      stressMax = computeMaxStress(res.d, fe, r);
      risky = hasRiskyClass(res.d, fe, r);
    } catch (e) {
      continue;
    }

    const amp = alpha > 1.01 ? 1 / (1 - 1 / alpha) : Infinity;
    const passAlpha = alpha >= 3.2;
    const passFreq = !mres.bad && mres.minF >= 1.02;
    const passComp = compMax * amp <= 0.95;
    const passStress = stressMax <= 300;
    const passClass = !risky;

    const item = {
      res, mres, alpha, compMax, stressMax, amp, risky
    };

    if (!bestAny || res.mass < bestAny.res.mass) bestAny = item;

    if (passAlpha && passFreq && passComp && passStress && passClass) {
      const out = build(res.cfg, false);
      out.note =
        "attempt7 probe (not final): " + res.cfg.note +
        "; mass " + Math.round(res.mass) +
        " kg, maxUtil " + Number(r.maxUtil).toFixed(2) +
        ", sag " + r.sag + " mm, sway " + r.sway + " mm" +
        ", minF " + mres.minF.toFixed(2) + " Hz" +
        ", alpha " + (isFinite(alpha) ? alpha.toFixed(2) : "inf") +
        ", compMax " + compMax.toFixed(2) +
        ", stressMax " + stressMax.toFixed(0) + " MPa";
      return out;
    }
  }

  if (bestAny) {
    const res = bestAny.res;
    const out = build(res.cfg, false);
    out.note =
      "attempt7 probe (not final, conservative criteria not fully met): " +
      res.cfg.note +
      "; mass " + Math.round(res.mass) +
      " kg, maxUtil " + Number(res.r.maxUtil).toFixed(2) +
      ", sag " + res.r.sag + " mm, sway " + res.r.sway + " mm" +
      ", minF " + bestAny.mres.minF.toFixed(2) + " Hz" +
      ", alpha " + (isFinite(bestAny.alpha) ? bestAny.alpha.toFixed(2) : "inf") +
      ", compMax " + bestAny.compMax.toFixed(2) +
      ", stressMax " + bestAny.stressMax.toFixed(0) + " MPa" +
      ", riskyClass " + bestAny.risky;
    return out;
  }

  const fb = build(configs[0], false);
  fb.note = "fallback safe baseline (no practice-passing candidate)";
  return fb;
}

function design(site, analyse) {
  const H = 5.5;
  const xs = [0, 3.963, 7.925, 11.888, 15.85, 19.813, 23.775, 27.738, 31.7];
  const zL = -4.05;
  const zR = 4.05;
  const NOTE = "Two Pratt through-trusses above the deck (depth 5.5 m, top plan above the traffic envelope) with midpoint restrainers and rung-and-X-rope plan bracing above and below the deck; tubes sized to practice utilisation and an Euler margin of 3.5 on member lengths.";

  const RAW = [
    ["CHS33.7x2.6", 2.54, 3.1, 0.106],
    ["CHS42.4x3.2", 3.94, 7.6, 0.133],
    ["CHS48.3x3.2", 4.53, 11.6, 0.152],
    ["CHS60.3x3.2", 5.74, 23.5, 0.189],
    ["CHS60.3x4", 7.07, 28.2, 0.189],
    ["CHS76.1x3.2", 7.33, 48.8, 0.239],
    ["CHS76.1x4", 9.06, 59.1, 0.239],
    ["CHS88.9x4", 10.67, 96.3, 0.279],
    ["CHS88.9x5", 13.18, 116.4, 0.279],
    ["CHS114.3x4", 13.86, 211.1, 0.359],
    ["CHS114.3x5", 17.17, 256.9, 0.359],
    ["CHS139.7x5", 21.16, 480.5, 0.439],
    ["CHS139.7x6.3", 26.4, 588.6, 0.439],
    ["CHS168.3x5", 25.65, 855.8, 0.529],
    ["CHS168.3x6.3", 32.06, 1053.4, 0.529],
    ["CHS193.7x6.3", 37.09, 1630, 0.609],
    ["CHS193.7x8", 46.67, 2015.5, 0.609],
    ["CHS219.1x8", 53.06, 2959.6, 0.688],
    ["CHS244.5x8", 59.44, 4160.4, 0.768],
    ["CHS273x10", 82.62, 7154.1, 0.858],
    ["CHS323.9x10", 98.61, 12158.3, 1.018],
    ["CHS355.6x12.5", 134.74, 19852.2, 1.117],
    ["CHS406.4x12.5", 154.68, 30030.7, 1.277],
    ["CHS457x16", 221.67, 53959.4, 1.436]
  ];
  const CAT = RAW.map(function (r) {
    return { name: r[0], A: r[1], I: r[2], m: 0.785 * r[1] + 0.9 * r[3] };
  }).sort(function (p, q) { return p.m - q.m; });

  function catIndex(name) {
    for (let i = 0; i < CAT.length; i++) if (CAT[i].name === name) return i;
    return 0;
  }
  const ROPE = [20, 24, 32, 40];

  // nodes (deck stations L0..L8, R0..R8 already exist)
  const P = {};
  const nodes = [];
  for (let j = 0; j <= 8; j++) {
    P["L" + j] = [xs[j], 0, zL];
    P["R" + j] = [xs[j], 0, zR];
    P["TL" + j] = [xs[j], H, zL];
    P["TR" + j] = [xs[j], H, zR];
    nodes.push({ id: "TL" + j, x: xs[j], y: H, z: zL, joint: "pin" });
    nodes.push({ id: "TR" + j, x: xs[j], y: H, z: zR, joint: "pin" });
  }
  for (let j = 0; j <= 7; j++) {
    const xm = 0.5 * (xs[j] + xs[j + 1]);
    P["TLm" + j] = [xm, H, zL];
    P["TRm" + j] = [xm, H, zR];
    nodes.push({ id: "TLm" + j, x: xm, y: H, z: zL, joint: "pin" });
    nodes.push({ id: "TRm" + j, x: xm, y: H, z: zR, joint: "pin" });
  }

  // members
  const mem = [];
  function add(a, b, kind) { mem.push({ a: a, b: b, kind: kind }); }
  const sides = ["L", "R"];
  for (let si = 0; si < 2; si++) {
    const s = sides[si];
    const T = "T" + s;
    for (let j = 0; j <= 7; j++) {
      add(s + j, s + (j + 1), "deckchord");
      add(T + j, T + "m" + j, "topchord");
      add(T + "m" + j, T + (j + 1), "topchord");
      add(s + j, T + "m" + j, "restrainer");
    }
    for (let j = 0; j <= 8; j++) add(s + j, T + j, "vertical");
    for (let j = 0; j <= 3; j++) add(T + j, s + (j + 1), "diagonal");
    for (let j = 4; j <= 7; j++) add(T + (j + 1), s + j, "diagonal");
  }
  function tpos(s, k) {
    return (k % 2 === 0) ? ("T" + s + (k / 2)) : ("T" + s + "m" + ((k - 1) / 2));
  }
  for (let k = 0; k <= 16; k++) add(tpos("L", k), tpos("R", k), "toprung");
  for (let j = 0; j <= 8; j++) add("L" + j, "R" + j, "deckrung");
  for (let k = 0; k <= 15; k++) {
    add(tpos("L", k), tpos("R", k + 1), "toprope");
    add(tpos("R", k), tpos("L", k + 1), "toprope");
  }
  for (let j = 0; j <= 7; j++) {
    add("L" + j, "R" + (j + 1), "deckrope");
    add("R" + j, "L" + (j + 1), "deckrope");
  }

  function initialState(kind) {
    if (kind === "deckchord" || kind === "topchord" || kind === "diagonal") return { t: "tube", c: catIndex("CHS139.7x6.3") };
    if (kind === "vertical") return { t: "tube", c: catIndex("CHS219.1x8") };
    if (kind === "restrainer") return { t: "tube", c: catIndex("CHS60.3x3.2") };
    if (kind === "toprung" || kind === "deckrung") return { t: "tube", c: catIndex("CHS114.3x5") };
    return { t: "rope", r: 0 };
  }
  const st = mem.map(function (m) { return initialState(m.kind); });

  function specOf(s) {
    if (s.t === "rope") return "WIRE WIRE" + ROPE[s.r] + " GALV";
    return "S690 " + CAT[s.c].name + " PAINT";
  }
  function lenOf(m) {
    const p = P[m.a];
    const q = P[m.b];
    const dx = q[0] - p[0];
    const dy = q[1] - p[1];
    const dz = q[2] - p[2];
    return Math.sqrt(dx * dx + dy * dy + dz * dz);
  }
  // smallest CHS meeting strength (S690, gammaM 1.25, utilisation ~0.85),
  // a compression allowance (chi >= 0.7), a fatigue allowance and Euler alpha >= 3.5
  function pickTube(Nt, Nc, L) {
    const Areq = Math.max(Nt / 46.9, Nc / 32.8, (Nt + Nc) / 35.75);
    const Ireq = 0.16884 * Nc * L * L;
    for (let i = 0; i < CAT.length; i++) {
      if (CAT[i].A >= Areq && CAT[i].I >= Ireq) return i;
    }
    return CAT.length - 1;
  }
  function build(note) {
    return {
      note: note,
      final: true,
      nodes: nodes,
      members: mem.map(function (m, k) { return [m.a, m.b, specOf(st[k])]; })
    };
  }

  let lastDesign = null;
  let okDesign = null;
  for (let it = 0; it < 12; it++) {
    const d = build(NOTE);
    const res = analyse(d);
    if (!res || res.error) break;
    lastDesign = d;
    if (res.ok) okDesign = d;

    const list = res.members || [];
    const byId = {};
    for (let i = 0; i < list.length; i++) {
      const r = list[i];
      byId[r.id] = r;
      const parts = String(r.id).split("-");
      if (parts.length === 2) byId[parts[1] + "-" + parts[0]] = r;
    }

    let changes = 0;
    for (let k = 0; k < mem.length; k++) {
      const m = mem[k];
      const r = byId[m.a + "-" + m.b] || list[k] || {};
      const util = Number(r.util) || 0;
      const Nt = Math.max(0, Number(r.tension) || 0);
      const Nc = Math.max(0, Number(r.compression) || 0);
      const s = st[k];
      if (s.t === "rope") {
        if (util > 0.85 && s.r < ROPE.length - 1) {
          s.r += 1;
          changes += 1;
        }
        continue;
      }
      let want = pickTube(Nt, Nc, lenOf(m));
      if (util > 0.9 && want <= s.c) want = s.c + 1;
      if (want > CAT.length - 1) want = CAT.length - 1;
      if (want !== s.c) {
        s.c = want;
        changes += 1;
      }
    }
    if (changes === 0) break;
  }

  return okDesign || lastDesign || build(NOTE);
}

function design(site, analyse) {
  const NOTE = "Two Pratt side trusses 8.2 m deep whose top chords lean out to z = ±4.8 m so every member above the deck stays outside the traffic box, with triangulated top and deck plan bracing (two diagonals per top panel, one per deck panel, deck X added only if flagged as a mechanism), members sized by practice utilisation in painted S690 CHS tubes with pinned welded joints.";
  const xs = [0, 3.963, 7.925, 11.888, 15.85, 19.813, 23.775, 27.738, 31.7];
  const H = 8.2;
  const ZT = 4.8;

  const RAW = [
    ["CHS33.7x2.6", 2.54], ["CHS42.4x3.2", 3.94], ["CHS48.3x3.2", 4.53],
    ["CHS60.3x3.2", 5.74], ["CHS60.3x4", 7.07], ["CHS76.1x3.2", 7.33],
    ["CHS76.1x4", 9.06], ["CHS88.9x4", 10.67], ["CHS88.9x5", 13.18],
    ["CHS114.3x4", 13.86], ["CHS114.3x5", 17.17], ["CHS139.7x5", 21.16],
    ["CHS139.7x6.3", 26.4], ["CHS168.3x5", 25.65], ["CHS168.3x6.3", 32.06],
    ["CHS193.7x6.3", 37.09], ["CHS193.7x8", 46.67], ["CHS219.1x8", 53.06],
    ["CHS244.5x8", 59.44], ["CHS273x10", 82.62], ["CHS323.9x10", 98.61],
    ["CHS355.6x12.5", 134.74], ["CHS406.4x12.5", 154.68], ["CHS457x16", 221.67]
  ];
  const CAT = RAW.map(function (r) { return { name: r[0], A: r[1] }; })
    .sort(function (p, q) { return p.A - q.A; });
  const SZ = CAT.length;

  function catIdx(name) {
    for (let i = 0; i < SZ; i++) if (CAT[i].name === name) return i;
    return 0;
  }

  const START = {
    deckchord: "CHS139.7x5",
    topchord: "CHS139.7x5",
    vertical: "CHS139.7x5",
    diag: "CHS114.3x5",
    toprung: "CHS76.1x4",
    topdiag: "CHS60.3x4",
    topx: "CHS60.3x4",
    deckrung: "CHS76.1x4",
    deckdiag: "CHS60.3x4",
    deckx: "CHS60.3x4"
  };

  const nodes = [];
  for (let j = 0; j <= 8; j++) {
    nodes.push({ id: "TL" + j, x: xs[j], y: H, z: -ZT, joint: "pin" });
    nodes.push({ id: "TR" + j, x: xs[j], y: H, z: ZT, joint: "pin" });
  }

  const mem = [];
  function addM(a, b, kind) {
    mem.push({ a: a, b: b, kind: kind, idx: catIdx(START[kind]) });
  }

  for (let s = 0; s < 2; s++) {
    const d = s === 0 ? "L" : "R";
    const t = s === 0 ? "TL" : "TR";
    for (let j = 0; j < 8; j++) addM(d + j, d + (j + 1), "deckchord");
    for (let j = 0; j < 8; j++) addM(t + j, t + (j + 1), "topchord");
    for (let j = 0; j <= 8; j++) addM(d + j, t + j, "vertical");
    for (let j = 0; j < 8; j++) {
      if (j <= 3) addM(t + j, d + (j + 1), "diag");
      else addM(t + (j + 1), d + j, "diag");
    }
  }
  for (let j = 0; j <= 8; j++) addM("TL" + j, "TR" + j, "toprung");
  for (let j = 0; j < 8; j++) {
    if (j % 2 === 0) addM("TL" + j, "TR" + (j + 1), "topdiag");
    else addM("TR" + j, "TL" + (j + 1), "topdiag");
  }
  for (let j = 0; j < 8; j++) {
    if (j % 2 === 0) addM("TR" + j, "TL" + (j + 1), "topx");
    else addM("TL" + j, "TR" + (j + 1), "topx");
  }
  for (let j = 0; j <= 8; j++) addM("L" + j, "R" + j, "deckrung");
  for (let j = 0; j < 8; j++) {
    if (j % 2 === 0) addM("L" + j, "R" + (j + 1), "deckdiag");
    else addM("R" + j, "L" + (j + 1), "deckdiag");
  }

  function addDeckX() {
    for (let j = 0; j < 8; j++) {
      if (j % 2 === 0) addM("R" + j, "L" + (j + 1), "deckx");
      else addM("L" + j, "R" + (j + 1), "deckx");
    }
  }

  function specOf(i) { return "S690 " + CAT[i].name + " PAINT"; }
  function build(flag) {
    return {
      note: NOTE,
      final: flag,
      nodes: nodes,
      members: mem.map(function (m) { return [m.a, m.b, specOf(m.idx)]; })
    };
  }

  let deckXAdded = false;
  let okDesign = null;
  let lastDesign = null;

  for (let it = 0; it < 14; it++) {
    const d = build(false);
    const res = analyse(d);
    if (!res || res.error) break;
    lastDesign = d;
    if (res.ok) okDesign = d;

    if (res.mechanism) {
      if (!deckXAdded) {
        addDeckX();
        deckXAdded = true;
        continue;
      }
      break;
    }

    const list = res.members || [];
    if (list.length === 0) break;

    const byKey = {};
    for (let i = 0; i < list.length; i++) {
      const p = String(list[i].id).split("-");
      if (p.length >= 2) {
        const a = p[0].trim();
        const b = p[1].trim().split(/\s+/)[0];
        byKey[[a, b].sort().join("|")] = list[i];
      }
    }

    let changes = 0;
    for (let k = 0; k < mem.length; k++) {
      const m = mem[k];
      const r = byKey[[m.a, m.b].sort().join("|")] || list[k] || {};
      const u = Number(r.util) || 0;
      const cur = m.idx;
      const A0 = CAT[cur].A;
      let target = cur;
      if (u > 0.75) {
        while (target < SZ - 1 && (u * A0) / CAT[target].A > 0.7) target++;
      } else if (u < 0.3) {
        while (target > 0 && (u * A0) / CAT[target - 1].A <= 0.6) target--;
      }
      if (target !== cur) {
        m.idx = target;
        changes++;
      }
    }
    if (changes === 0 && res.ok) break;
  }

  return okDesign || lastDesign || build(false);
}

function design(site, analyse) {
  const NOTE = "Two-wall box girder on the traffic-box side faces (z=±4.05): a Pratt web above the deck to a top chord at y=8.25, a bottom tier to y=-5.5 with deck chords, and top, deck and bottom plates triangulated across the walls so every cross-section is rigid with nothing crossing the clearance box; painted S690 CHS sized by practice utilisation.";
  const xs = [0, 3.963, 7.925, 11.888, 15.85, 19.813, 23.775, 27.738, 31.7];
  const YT = 8.25;
  const YB = -5.5;
  const ZW = 4.05;

  const RAW = [
    ["CHS33.7x2.6", 2.54], ["CHS42.4x3.2", 3.94], ["CHS48.3x3.2", 4.53],
    ["CHS60.3x3.2", 5.74], ["CHS60.3x4", 7.07], ["CHS76.1x3.2", 7.33],
    ["CHS76.1x4", 9.06], ["CHS88.9x4", 10.67], ["CHS88.9x5", 13.18],
    ["CHS114.3x4", 13.86], ["CHS114.3x5", 17.17], ["CHS139.7x5", 21.16],
    ["CHS139.7x6.3", 26.4], ["CHS168.3x5", 25.65], ["CHS168.3x6.3", 32.06],
    ["CHS193.7x6.3", 37.09], ["CHS193.7x8", 46.67], ["CHS219.1x8", 53.06],
    ["CHS244.5x8", 59.44], ["CHS273x10", 82.62], ["CHS323.9x10", 98.61],
    ["CHS355.6x12.5", 134.74], ["CHS406.4x12.5", 154.68], ["CHS457x16", 221.67]
  ];
  const CAT = RAW.map(function (r) { return { name: r[0], A: r[1] }; })
    .sort(function (p, q) { return p.A - q.A; });
  const SZ = CAT.length;

  function catIdx(name) {
    for (let i = 0; i < SZ; i++) if (CAT[i].name === name) return i;
    return 0;
  }

  const KIND = {
    tc: { start: "CHS168.3x6.3", floor: "CHS114.3x5", target: 0.6 },
    bc: { start: "CHS88.9x5", floor: "CHS60.3x4", target: 0.6 },
    dc: { start: "CHS114.3x5", floor: "CHS76.1x4", target: 0.6 },
    tv: { start: "CHS193.7x6.3", floor: "CHS114.3x5", target: 0.45 },
    bv: { start: "CHS139.7x5", floor: "CHS88.9x5", target: 0.45 },
    td: { start: "CHS139.7x5", floor: "CHS88.9x5", target: 0.45 },
    bd: { start: "CHS114.3x5", floor: "CHS88.9x5", target: 0.45 },
    pl: { start: "CHS88.9x4", floor: "CHS60.3x3.2", target: 0.4 },
    px: { start: "CHS88.9x4", floor: "CHS60.3x3.2", target: 0.4 }
  };

  const nodes = [];
  for (let j = 0; j <= 8; j++) {
    nodes.push({ id: "TL" + j, x: xs[j], y: YT, z: -ZW, joint: "pin" });
    nodes.push({ id: "TR" + j, x: xs[j], y: YT, z: ZW, joint: "pin" });
    nodes.push({ id: "BL" + j, x: xs[j], y: YB, z: -ZW, joint: "pin" });
    nodes.push({ id: "BR" + j, x: xs[j], y: YB, z: ZW, joint: "pin" });
  }

  const mem = [];
  function addM(a, b, kind) {
    mem.push({ a: a, b: b, kind: kind, idx: catIdx(KIND[kind].start) });
  }

  const SIDES = [["L", "TL", "BL"], ["R", "TR", "BR"]];
  SIDES.forEach(function (s) {
    const D = s[0], T = s[1], B = s[2];
    for (let j = 0; j < 8; j++) addM(D + j, D + (j + 1), "dc");
    for (let j = 0; j < 8; j++) addM(T + j, T + (j + 1), "tc");
    for (let j = 0; j < 8; j++) addM(B + j, B + (j + 1), "bc");
    for (let j = 0; j <= 8; j++) addM(D + j, T + j, "tv");
    for (let j = 0; j <= 8; j++) addM(D + j, B + j, "bv");
    for (let j = 0; j < 8; j++) {
      if (j < 4) addM(T + j, D + (j + 1), "td");
      else addM(D + j, T + (j + 1), "td");
    }
    for (let j = 0; j < 8; j++) {
      if (j < 4) addM(B + j, D + (j + 1), "bd");
      else addM(D + j, B + (j + 1), "bd");
    }
  });

  for (let j = 0; j <= 8; j++) {
    addM("TL" + j, "TR" + j, "pl");
    addM("BL" + j, "BR" + j, "pl");
    addM("L" + j, "R" + j, "pl");
  }
  for (let j = 0; j < 8; j++) {
    if (j % 2 === 0) {
      addM("TL" + j, "TR" + (j + 1), "pl");
      addM("BL" + j, "BR" + (j + 1), "pl");
      addM("L" + j, "R" + (j + 1), "pl");
    } else {
      addM("TR" + j, "TL" + (j + 1), "pl");
      addM("BR" + j, "BL" + (j + 1), "pl");
      addM("R" + j, "L" + (j + 1), "pl");
    }
  }

  function addX() {
    for (let j = 0; j < 8; j++) {
      if (j % 2 === 0) {
        addM("TR" + j, "TL" + (j + 1), "px");
        addM("BR" + j, "BL" + (j + 1), "px");
        addM("R" + j, "L" + (j + 1), "px");
      } else {
        addM("TL" + j, "TR" + (j + 1), "px");
        addM("BL" + j, "BR" + (j + 1), "px");
        addM("L" + j, "R" + (j + 1), "px");
      }
    }
  }

  function build(flag) {
    return {
      note: NOTE,
      final: flag,
      nodes: nodes,
      members: mem.map(function (m) {
        return [m.a, m.b, "S690 " + CAT[m.idx].name + " PAINT"];
      })
    };
  }

  function keyOf(a, b) { return [a, b].sort().join("|"); }

  let okDesign = null;
  let okMass = Infinity;
  let lastDesign = null;
  let xAdded = false;

  for (let it = 0; it < 12; it++) {
    const d = build(false);
    const res = analyse(d);
    if (!res || res.error) break;
    lastDesign = d;
    if (res.ok && Number(res.mass) < okMass) {
      okMass = Number(res.mass);
      okDesign = d;
    }
    if (res.mechanism) {
      if (!xAdded) { addX(); xAdded = true; continue; }
      break;
    }
    const list = res.members || [];
    if (list.length === 0) break;

    const byKey = {};
    for (let i = 0; i < list.length; i++) {
      const p = String(list[i].id).split("-");
      if (p.length >= 2) {
        const a = p[0].trim();
        const b = p[1].trim().split(/\s+/)[0];
        byKey[keyOf(a, b)] = list[i];
      }
    }

    let changes = 0;
    for (let k = 0; k < mem.length; k++) {
      const m = mem[k];
      const r = byKey[keyOf(m.a, m.b)] || list[k] || {};
      const u = Number(r.util) || 0;
      const kd = KIND[m.kind];
      const A0 = CAT[m.idx].A;
      let need = A0 * u / kd.target;
      if (need > 2.5 * A0) need = 2.5 * A0;
      if (need < 0.5 * A0) need = 0.5 * A0;
      let t = 0;
      while (t < SZ - 1 && CAT[t].A < need) t++;
      const fl = catIdx(kd.floor);
      if (t < fl) t = fl;
      if (t !== m.idx) { m.idx = t; changes++; }
    }
    if (changes === 0 && res.ok) break;
  }

  const out = okDesign || lastDesign || build(false);
  out.final = true;
  return out;
}
